\label{gcd graph dfn}
Let $G$ be a septuple $(\mu,\mathcal{V},\mathcal{W},\mathcal{E},\mathcal{P},f,g)$ such that:	
\begin{enumerate}
		\item $\mu$ is a measure on $\mathbb{N}$ such that $\mu(n)<\infty$ for all $n\in\mathbb{N}$; we extend to $\mathbb{N}^2$ by letting
	\[
	\mu(\mathcal{N}):=\sum_{(n_1,n_2)\in\mathcal{N}}\mu(n_1)\mu(n_2) 
	\quad\text{for}\quad\mathcal{N}\subseteq\mathbb{N}^2;	
	\]	
		\item $\mathcal{V}$ and $\mathcal{W}$ are finite sets of positive integers;
		\item $\mathcal{E}\subseteq\mathcal{V}\times \mathcal{W}$, that is to say $(\mathcal{V},\mathcal{W},\mathcal{E})$ is a bipartite graph;
		\item $\mathcal{P}$ is a set of primes;
		\item $f$ and $g$ are functions from $\mathcal{P}$ to $\mathbb{Z}_{\geqslant0}$ such that for all $p\in\mathcal{P}$ we have:
		\begin{enumerate}
		\item $p^{f(p)}|v$ for all $v\in\mathcal{V}$, and $p^{g(p)}|w$ for all $w\in\mathcal{W}$;
		\item if $(v,w)\in\mathcal{E}$, then $p^{\min\{f(p),g(p)\}}\|\gcd(v,w)$;
		\item if $f(p)\neq g(p)$, then $p^{f(p)}\|v$ for all $v\in\mathcal{V}$, and $p^{g(p)}\|w$ for all $w\in\mathcal{W}$.
		\end{enumerate}
\end{enumerate}
We then call $G$ a (bipartite) \emph{GCD graph} with \emph{sets of vertices} $(\mathcal{V},\mathcal{W})$, \emph{set of edges} $\mathcal{E}$ and \emph{multiplicative data} $(\mathcal{P},f,g)$. We will also refer to $\mathcal{P}$ as the \emph{set of primes} of $G$. If $\mathcal{P}=\emptyset$, we say that $G$ has \emph{trivial} set of primes and we view $f=f_\emptyset$ and $g=g_\emptyset$ as two copies of the empty function from $\emptyset$ to $\mathbb{Z}_{\geqslant 0}$.

\label{lem:Trivial} 
	Let $G_1,G_2,G_3$ be GCD graphs.
	\begin{enumerate} 	
				\item The property of being a GCD subgraph is transitive: If $G_1\preceq G_2$ and $G_2\preceq G_3$, then $G_1\preceq G_3$
				\item If $G_1\preceq G_2$, then $\mathcal{R}(G_1)\subseteq \mathcal{R}(G_2)$.
				\item If  $G_1=(\mu,\mathcal{V},\mathcal{W},\mathcal{E},\mathcal{P},f,g)$ is non-trivial, then $\mu(\mathcal{V}),\mu(\mathcal{W})>0$.
				\item Let $G_1$ have edge density $\delta$. Then the following are equivalent:
				\begin{enumerate}
					\item $G_1$ is non-trivial. 
					\item $\delta>0$.
					\item $q(G_1)>0$.
				\end{enumerate}
	\end{enumerate}

