\label{lem:HighDegreeSubgraph}
Let $G=(\mu,\mathcal{V},\mathcal{W},\mathcal{E},\mathcal{P},f,g)$ be a GCD graph with edge density $\delta>0$. Then there is a GCD subgraph $G'=(\mu,\mathcal{V}',\mathcal{W}',\mathcal{E}',\mathcal{P},f,g)$ of $G$ with edge density $\delta'>0$ such that:
\begin{enumerate}
\item $q(G')\geqslant q(G)$;
\item $\delta'\geqslant \delta$;
\item For all $v\in\mathcal{V}'$ and for all $w\in\mathcal{W}'$, we have
\[
\mu(\Gamma_{G'}(v))\geqslant\frac{9\delta'}{10}\mu(\mathcal{W}')
\quad\text{and}\quad \mu(\Gamma_{G'}(w))\geqslant\frac{9\delta'}{10}\mu(\mathcal{V}').
\]
\end{enumerate}

\label{lem:HighDegree}
Let	$G=(\mu,\mathcal{V},\mathcal{W},\mathcal{E},\mathcal{P},f,g)$ be a GCD graph with edge density $\delta>0$. For each $v\in\mathcal{V}$ and for each $w\in\mathcal{W}$, we let
\[
\Gamma_G(v):=\{w\in\mathcal{W}:\,(v,w)\in\mathcal{E}\}
\quad\text{and}\quad
\Gamma_G(w):=\{v\in\mathcal{V}:\,(v,w)\in\mathcal{E}\}
\]
be the sets of their neighbours. Then one of the following holds:
\begin{enumerate}
\item For all $v\in\mathcal{V}$ and for all $w\in\mathcal{W}$, we have
\[
\mu(\Gamma_G(v))\geqslant\frac{9\delta}{10}\mu(\mathcal{W})
\quad\text{and}\quad \mu(\Gamma_G(w))\geqslant\frac{9\delta}{10}\mu(\mathcal{V}).
\]
\item There is a GCD subgraph $G'=(\mu,\mathcal{V}',\mathcal{W}',\mathcal{E}',\mathcal{P},f,g)$ of $G$ with edge density $\delta'\geqslant \delta$, quality $q(G')\geqslant q(G)$, and such that either $\mathcal{V}'\subsetneq\mathcal{V}$ or $\mathcal{W}'\subsetneq \mathcal{W}$.
\end{enumerate}

\label{lem:InducedGraphs}
Let $G=(\mu,\mathcal{V},\mathcal{W},\mathcal{E},\mathcal{P},f,g)$ be a GCD graph, $p\in\mathcal{R}(G)$ and $k,\ell\in\mathbb{Z}_{\geqslant0}$. If $G_{p^k,p^\ell}$ is as in Definition \ref{def:special graphs}, then $G_{p^k,p^\ell}$ is a GCD subgraph of $G$. In addition, if $G$ is non-trivial and $\mu(\mathcal{V}_{p^k}),\mu(\mathcal{W}_{p^\ell})>0$, then we have
\[
\frac{q(G_{p^k,p^\ell})}{q(G)}
	=\bigg(\frac{\mu(\mathcal{E}_{p^k,p^\ell})}{\mu(\mathcal{E})}\bigg)^{10}
	 \bigg(\frac{\mu(\mathcal{V})}{\mu(\mathcal{V}_{p^k})}\bigg)^{9}
	 \bigg(\frac{\mu(\mathcal{W})}{\mu(\mathcal{W}_{p^\ell})}\bigg)^{9}
	 \frac{p^{|k-\ell|}}{(1-\mathds{1}_{k=\ell\geqslant1}/p)^2(1-1/p^{31/30})^{10}}.
\]

 Assume that conclusion $(b)$ does not hold, so $\sum_{\ell\in\mathcal{L}_{k,r}}  \mu(\mathcal{E}_{p^k,p^\ell})>\mu(\mathcal{E})/(4p^{31/30})$ and we wish to establish $(a)$. Then there must exist some $\ell\in\mathcal{L}_{k,r}$ such that 
\[
\mu(\mathcal{E}_{p^k,p^\ell}) > \frac{\mu(\mathcal{E})}{300\cdot2^{|k-\ell|/20}p^{31/30}} >0 ,
\]
where we used that $\sum_{|j|\geqslant 0}2^{-|j|/20}\leqslant 2/(1-2^{-1/20})\leqslant 60$. In particular, $G_{p^k,p^\ell}$ is a non-trivial GCD graph. Since $\mu(\mathcal{W}_{p^k})\geqslant (1-10^{40}/p)\mu(\mathcal{W})$, we have that $\mu(\mathcal{W}_{p^\ell})\leqslant 10^{40}\mu(\mathcal{W})/p$. Consequently,
\begin{align*}
\frac{q(G_{p^k,p^\ell})}{q(G)}
	&= \bigg(\frac{\mu(\mathcal{E}_{p^k,p^\ell})}{\mu(\mathcal{E})}\bigg)^{10}
	\bigg(\frac{\mu(\mathcal{V})}{\mu(\mathcal{V}_{p^k})}\bigg)^{9}
	\bigg(\frac{\mu(\mathcal{W})}{\mu(\mathcal{W}_{p^\ell})}\bigg)^{9} \frac{p^{|k-\ell|}}{(1-1/p^{31/30})^{10}} \\
	&\geqslant \Big(\frac{1}{300\cdot 2^{|k-\ell|/20}p^{31/30}}\Big)^{10}
	\Big(\frac{p}{10^{40}}\Big)^{9} p^{|k-\ell|} \\
	&\geqslant \frac{p^{-4/3}(p/2^{1/2})^{|k-\ell|}}{10^{25}10^{40\cdot 9}}.
\end{align*}
Since $|k-\ell|\geqslant r+1\geqslant 2r/3+4/3$, we have 
\[
p^{-4/3}(p/2^{1/2})^{|k-\ell|}\geqslant 2^{-4/3}(p/2^{1/2})^{2r/3}.
\]
In addition, note that $(p/2^{1/2})\geqslant p^{1/2}$ for all primes. Therefore
\begin{align*}
\frac{q(G_{p^k,p^\ell})}{q(G)}	&\geqslant \frac{p^{r/3}}{2^{4/3}\cdot 10^{385}}
	>2
\end{align*}
by our assumption that $p^r>10^{2000}$. 

Similarly, we have 
\begin{align*}
\frac{\delta_{p^k,p^\ell}}{\delta}\cdot \frac{q(G_{p^k,p^\ell})}{q(G)}
&= \bigg(\frac{\mu(\mathcal{E}_{p^k,p^\ell})}{\mu(\mathcal{E})}\bigg)^{11}
\bigg(\frac{\mu(\mathcal{V})}{\mu(\mathcal{V}_{p^k})}\bigg)^{10}
\bigg(\frac{\mu(\mathcal{W})}{\mu(\mathcal{W}_{p^\ell})}\bigg)^{10} \frac{p^{|k-\ell|}}{(1-1/p^{31/30})^{10}} \\
&\geqslant \bigg(\frac{1}{300\cdot 2^{|k-\ell|/20}p^{31/30}}\bigg)^{11}
\bigg(\frac{p}{10^{40}}\bigg)^{10} p^{|k-\ell|} \\
&\geqslant \frac{p^{-41/30}(p/2^{11/20})^{|k-\ell|}}{10^{428}}\\
&\geqslant\frac{(p/2^{11/20})^{19r/30}}{2^{41/30\cdot 11/20}\cdot 10^{428}}.
\end{align*}
Since $p/2^{11/20}\geqslant p^{9/20}$ and $p^r>10^{2000}$, we conclude that 
\[
\frac{\delta_{p^k,p^\ell}}{\delta}\cdot \frac{q(G_{p^k,p^\ell})}{q(G)}>2.
\]
This completes the proof of the lemma.

\label{lem:UnbalancedSetEdges2}
Let $G=(\mu,\mathcal{V},\mathcal{W},\mathcal{E},\mathcal{P},f,g)$ be a GCD graph with edge density $\delta>0$. Let $p\in\mathcal{R}(G)$,  $r\in\mathbb{Z}_{\geqslant 1}$ and $\ell\in\mathbb{Z}_{\geqslant0}$ be such that $p^r>10^{2000}$ and
\[
\frac{\mu(\mathcal{V}_{p^\ell})}{\mu(\mathcal{V})}\geqslant 1-\frac{10^{40}}{p},
\]
and set $\mathcal{K}_{\ell,r}=\{k\in\mathbb{Z}_{\geqslant0}:|\ell-k|\geqslant r+1\}$. If $\delta_{p^k,p^\ell}$ denotes the edge density of the graph $G_{p^k,p^\ell}$, then one of the following holds:
\begin{enumerate}
\item There is $k\in\mathcal{K}_{\ell,r}$ such that $q(G_{p^k,p^\ell})>2q(G)$ and $\delta_{p^k,p^\ell}q(G_{p^k,p^\ell})>2\delta q(G)>0$.
\item $\sum_{k\in\mathcal{K}_{\ell,r}}  \mu(\mathcal{E}_{p^k,p^\ell})\leqslant\mu(\mathcal{E})/(4p^{31/30})$.
\end{enumerate}

\label{lem:SmallSetEdges}
Let	$G=(\mu,\mathcal{V},\mathcal{W},\mathcal{E},\mathcal{P},f,g)$ be a GCD graph with edge density $\delta>0$ and let $\eta\in(0,1)$. Then one of the following holds:
\begin{enumerate}
	\item For all sets $\mathcal{A}\subseteq\mathcal{V}$ and $\mathcal{B}\subseteq\mathcal{W}$ such that $\mu(\mathcal{A})\leqslant \eta\cdot  \mu(\mathcal{V})$ and  $\mu(\mathcal{B})\leqslant\eta \cdot \mu(\mathcal{W})$, we have $\mu(\mathcal{E}\cap(\mathcal{A}\times\mathcal{B}))\leqslant \eta^{9/5}\cdot \mu(\mathcal{E})$.
	\item There is a GCD subgraph $G'=(\mu,\mathcal{V}',\mathcal{W}',\mathcal{E}',\mathcal{P},f,g)$ of $G$ such that $q(G')>q(G)$,  $\mathcal{V}'\subsetneq \mathcal{V}$ and $\mathcal{W}'\subsetneq \mathcal{W}$.
\end{enumerate}

Assume that (a) fails. Hence, there exist sets $\mathcal{A}\subseteq\mathcal{V}$ and $\mathcal{B}\subseteq\mathcal{W}$ such that $\mu(\mathcal{A})\leqslant\eta \cdot \mu(\mathcal{V})$, $\mu(\mathcal{B})\leqslant\eta \cdot \mu(\mathcal{W})$ and $\mu(\mathcal{E}\cap(\mathcal{A}\times\mathcal{B}))>\eta^{9/5}\cdot \mu(\mathcal{E})$. We then set $\mathcal{E}'=\mathcal{E}\cap(\mathcal{A}\times \mathcal{B})$ and consider the GCD subgraph $G'=(\mu,\mathcal{A},\mathcal{B},\mathcal{E}',\mathcal{P},f,g)$ of $G$. Since $\mu(\mathcal{E}')>0$, this is a non-trivial GCD graph. In addition, since $\mu(\mathcal{V})>0$ (because $G$ is non-trivial) and $\eta<1$ (by assumption), we have $\mu(\mathcal{A})\leqslant \eta \mu(\mathcal{V})<\mu(\mathcal{V})$, and thus $\mathcal{A}\subsetneq \mathcal{V}$. Similarly, we find that $\mathcal{B}\subsetneq \mathcal{W}$. Finally, for the quality of $G'$, we have
\[
\frac{q(G')}{q(G)}
	= \bigg(\frac{\mu(\mathcal{E}')}{\mu(\mathcal{E})}\bigg)^{10}
	\bigg(\frac{\mu(\mathcal{V})}{\mu(\mathcal{A})}\bigg)^{9}
	\bigg(\frac{\mu(\mathcal{W})}{\mu(\mathcal{B})}\bigg)^{9} >\frac{(\eta^{9/5})^{10}}{\eta^9\cdot\eta^9}=1.
\]
This completes the proof of the lemma.

