Then there exist $k,\ell\in \mathbb{Z}_{\geqslant0}$ such that $\alpha_k,\beta_\ell>0$ and
\[
\frac{\mu(\mathcal{E}_{p^k,p^\ell})}{\mu(\mathcal{E})} 	
	\geqslant 	
		\begin{cases}
		(\alpha_k\beta_k)^{9/10}
						&\text{if}\ k=\ell,\\
						\\
			\displaystyle\frac{\alpha_k(1-\beta_k)
				+\beta_k(1-\alpha_k)
				+\alpha_{\ell}(1-\beta_\ell)
				+\beta_\ell(1-\alpha_\ell)}{2^{|k-\ell|/20}\times 1000}
						&\text{otherwise}.
		\end{cases}
\]

 Let $\alpha_k$ and $\beta_\ell$ be defined as in the statement of Lemma \ref{lem:EdgeSets}. Consequently, there are $k,\ell\in\mathbb{Z}_{\geqslant0}$ such that $\alpha_k,\beta_\ell>0$ and
\begin{equation}\label{eq:FirstPigeonholeArgument}
\frac{\mu(\mathcal{E}_{p^k,p^\ell})}{\mu(\mathcal{E})} 	
\geqslant 	
\begin{cases}
(\alpha_{k}\beta_{k})^{9/10}
&\text{if}\ k=\ell,\\
\\
\displaystyle\frac{\alpha_k(1-\beta_k)
	+\beta_k(1-\alpha_k)
	+\alpha_\ell(1-\beta_\ell)
	+\beta_\ell(1-\alpha_\ell)}{2^{|k-\ell|/20}\times 1000}
&\text{otherwise}.
\end{cases}
\end{equation}
In particular, $\mu(\mathcal{E}_{p^k,p^\ell})>0$, so that $G_{p^k,p^\ell}$ is a non-trivial GCD subgraph of $G$. We separate two cases, according to whether $k=\ell$ or not.

\bigskip

\noindent 
\textit{Case 1: $k=\ell$.}

\medskip

Let $G'=G_{p^k,p^k}$. Lemma \ref{lem:InducedGraphs} and our lower bound $\mu(\mathcal{E}_{p^k,p^k})\geqslant (\alpha_k\beta_k)^{9/10}\mu(\mathcal{E})$ imply that
\als{
\frac{q(G')}{q(G)}	=\bigg(\frac{\mu(\mathcal{E}_{p^k,p^k})}{\mu(\mathcal{E})}\bigg)^{10}
	(\alpha_k\beta_k)^{-9}
	\frac{1}{(1-\mathds{1}_{k\geqslant1}/p)^2(1-1/p^{31/30})^{10}} \geqslant1.
}
In addition,
\[
\frac{\delta'}{\delta} 
	= \frac{\mu(\mathcal{E}_{p^k,p^k})}{\mu(\mathcal{E})} \cdot
	 \frac{\mu(\mathcal{V})\mu(\mathcal{W})}{\mu(\mathcal{V}_{p^k})\mu(\mathcal{W}_{p^k})}  
	\geqslant (\alpha_{k}\beta_{k})^{9/10}\frac{1}{\alpha_k\beta_k} \geqslant 1.
\]
This establishes conclusion  (a) in this case, noting that $f'(p)=g'(p)=k$ so $\mathds{1}_{f'(p)\ne g'(p)}=0$.


\bigskip

\noindent 
\textit{Case 2: $k\ne \ell$}

\medskip

As before, we let $G'=G_{p^k,p^\ell}$, and use Lemma \ref{lem:InducedGraphs} and our lower bound on $\mathcal{E}_{p^k,p^\ell}$ to find that
\als{
	\frac{q(G')}{q(G)}
	&=\bigg(\frac{\mu(\mathcal{E}_{p^k,p^\ell})}{\mu(\mathcal{E})}\bigg)^{10}
	(\alpha_k\beta_\ell)^{-9}
	\frac{p^{|k-\ell|}}{(1-1/p^{31/30})^{10}} \\
	&\geqslant\frac{S^{10}}{1000^{10}(\alpha_k\beta_\ell)^{9}}
		\cdot \Big(\frac{p}{2^{1/2}}\Big)^{|k-\ell|},
}
where
\[
S=\alpha_k(1-\beta_k)
+\beta_k(1-\alpha_k)
+\alpha_\ell(1-\beta_\ell)
+\beta_\ell(1-\alpha_\ell).
\]
In addition, we have
\als{
\frac{\delta'}{\delta}\cdot \frac{q(G')}{q(G)}
	&=\bigg(\frac{\mu(\mathcal{E}_{p^k,p^\ell})}{\mu(\mathcal{E})}\bigg)^{11}
	(\alpha_k\beta_\ell)^{-10}
	\frac{p^{|k-\ell|}}{(1-1/p^{31/30})^{10}} \\
	&\geqslant\frac{S^{11}}{1000^{11}(\alpha_k\beta_\ell)^{10}}
		\cdot \Big(\frac{p}{2^{11/20}}\Big)^{|k-\ell|} .
}
Note that 
\eq{\label{S lb1}
S\geqslant \alpha_k(1-\beta_k)\geqslant \alpha_k\beta_\ell.
}
Indeed, this follows by our assumption that $k\neq\ell$, which implies that $\beta_k+\beta_\ell\leqslant \sum_{j\geqslant 0}\beta_j=1$. Combining the above, we conclude that
\eq{\label{q'/q-lb}
	\min\bigg\{ \frac{q(G')}{q(G)},\frac{\delta'}{\delta}\cdot \frac{q(G')}{q(G)} \bigg\}
	\geqslant\frac{S^{2}}{1000^{11}\alpha_k\beta_\ell}
		\cdot \Big(\frac{p}{2^{11/20}}\Big)^{|k-\ell|}.
}

Now, assume that conclusion (a) of the lemma does not hold, so that the left hand side of \eqref{q'/q-lb} is $\leqslant2$. Since $|k-\ell|\geqslant1$ and all primes are at least $2$, we must then have that
\[
S\leqslant \frac{S^{2}}{\alpha_k\beta_\ell}
\leqslant 2\cdot 10^{33}\bigg(\frac{2^{11/20}}{p}\bigg)^{|k-\ell|}\leqslant\frac{10^{34}}{p}
\leqslant\frac{1}{5},
\]
where we used our assumption that $p\geqslant 10^{40}$ for the last inequality. In particular, this gives
\begin{equation}\label{small quality}
S\leqslant  \frac{10^{34}}{p}
\quad\text{and}\quad
\frac{S^2}{\alpha_k\beta_\ell}\leqslant \frac{1}{5}.
\end{equation}

We note that
\begin{equation}
S\geqslant\alpha_k(1-\beta_k)+\beta_\ell(1-\alpha_\ell)\geqslant (\alpha_k+\beta_\ell)(1-\max\{\alpha_\ell,\beta_k\}).
\label{eq:SBound}
\end{equation}
Thus by the arithmetic-geometric mean inequality, and relations \eqref{eq:SBound} and \eqref{small quality}, we have
\[
(1-\max\{\alpha_\ell,\beta_k\})^2\leqslant  \frac{(\alpha_k+\beta_\ell)^2}{4\alpha_k\beta_\ell}(1-\max\{\alpha_\ell,\beta_k\})^2\leqslant \frac{S^2}{4\alpha_k\beta_\ell}\leqslant \frac{1}{20}.
\]
In particular, $\max\{\alpha_\ell,\beta_k\}\geqslant 1/2$.

We consider the case when $\beta_k\geqslant1/2$; the case with $\alpha_\ell\geqslant 1/2$ is entirely analogous with the roles of $\beta$ and $\alpha$ swapped, and the roles of $k$ and $\ell$ swapped. Thus, to complete the proof of the lemma, it suffices to show that
\begin{equation}\label{small quality - large structure}
\alpha_k,\beta_k
	\geqslant1-\frac{10^{40}}{p}.
\end{equation}
The first inequality of \eqref{small quality} states that
\[
\alpha_k(1-\beta_k)
+\beta_k(1-\alpha_k)
+\alpha_\ell(1-\beta_\ell)
+\beta_\ell(1-\alpha_\ell)
	\leqslant \frac{10^{34}}{p}.
\]
Since $\beta_k\geqslant1/2$, we infer that
\[
1-\alpha_k\leqslant 2\beta_k(1-\alpha_k)\leqslant 
	\frac{2\cdot 10^{34}}{p}\leqslant \frac{10^{35}}{p} \leqslant \frac{1}{2}. 
\]
In particular, $\alpha_k\geqslant 1-10^{40}/p$ and $\alpha_k\geqslant1/2$, whence
\[
1-\beta_k\leqslant 2\alpha_k(1-\beta_k)\leqslant 
\frac{2\cdot 10^{34}}{p}\leqslant \frac{10^{40}}{p}.
\]
This completes the proof of \eqref{small quality - large structure} and hence of the lemma.

\label{lem:MainLem2} 
Consider a GCD graph $G=(\mu,\mathcal{V},\mathcal{W},\mathcal{E},\mathcal{P},f,g)$ with edge density $\delta>0$ and let $p\in\mathcal{R}(G)$ be a prime with $p\geqslant 10^{2000}$. Then there is a GCD subgraph $G'$ of $G$ with set of primes $\mathcal{P}'=\mathcal{P}\cup\{p\}$ such that
\[
\mathcal{R}(G')\subseteq\mathcal{R}(G)\setminus\{p\}
\quad\text{and}\quad  q(G')\geqslant q(G)>0.
\]

 First of all, we may assume without loss of generality that for all sets $\mathcal{A}\subseteq \mathcal{V}$ and $\mathcal{B}\subseteq \mathcal{W}$, we have that 
\begin{equation}\label{eq:NoEdgesBetweenSmallSets}
\mu(\mathcal{E}\cap(\mathcal{A}\times \mathcal{B})) \leqslant \frac{\mu(\mathcal{E})}{2p^{3/2}} 
\quad\text{whenever}\quad \max\bigg\{ \frac{\mu(\mathcal{A})}{\mu(\mathcal{V})}, \frac{\mu(\mathcal{B})}{\mu(\mathcal{W})} \bigg\} \leqslant \frac{10^{40}}{p} .
\end{equation}
Indeed, if $G$ does not satisfy \eqref{eq:NoEdgesBetweenSmallSets}, then we apply Lemma \ref{lem:NoSmallSetEdges} with $\eta=10^{40}/p$ to replace $G$ by a non-trivial subgraph $G^{(1)}$ that does have this property (noticing that $(10^{40}/p)^{9/5}\leqslant 1/(2p^{3/2})$ for $p\geqslant 10^{2000}$). In addition, $G^{(1)}$ has the same multiplicative data as $G$ and its quality is strictly larger. Hence, we may work with $G^{(1)}$ instead. So, from now on, we assume that \eqref{eq:NoEdgesBetweenSmallSets} holds. 

We now apply Lemma \ref{lem:MainLem}. If conclusion $(a)$ of Lemma \ref{lem:MainLem} holds, then we are done. Thus we may assume that conclusion $(b)$ holds, that is to say there is some $k\in\mathbb{Z}_{\geqslant0}$ such that 
\[
\frac{\mu(\mathcal{V}_{p^k})}{\mu(\mathcal{V})}\geqslant1-\frac{10^{40}}{p}
\quad\text{and}\quad
\frac{\mu(\mathcal{W}_{p^k})}{\mu(\mathcal{W})}\geqslant 1-\frac{10^{40}}{p}.
\]
In particular, by \eqref{eq:NoEdgesBetweenSmallSets} we see that
\begin{equation}\label{eq:NoBadEdges1}
\mu\big(\mathcal{E}(\mathcal{V}\setminus\mathcal{V}_{p^k},\mathcal{W}\setminus \mathcal{W}_{p^k})\big) 
\leqslant \frac{\mu(\mathcal{E})}{2p^{3/2}}.
\end{equation}

Now, set
\[
\widetilde{\mathcal{V}}_{p^k}=\mathcal{V}_{p^{k-1}}\cup\mathcal{V}_{p^k}\cup\mathcal{V}_{p^{k+1}}
\quad\text{and}\quad
\widetilde{\mathcal{W}}_{p^k}=\mathcal{W}_{p^{k-1}}\cup\mathcal{W}_{p^k}\cup\mathcal{W}_{p^{k+1}} ,
\]
with the convention that $\mathcal{V}_{p^{-1}}=\emptyset=\mathcal{W}_{p^{-1}}$. 
In view of Lemmas \ref{lem:UnbalancedSetEdges1} and \ref{lem:UnbalancedSetEdges2} applied with $r=1$, we may assume that 
\begin{equation}\label{eq:NoBadEdges2}
\mu\big(\mathcal{E}(\mathcal{V}\setminus\widetilde{\mathcal{V}}_{p^k},\mathcal{W}_{p^k})\big)
	= \sum_{\substack{i\geqslant0 \\ |i-k|\geqslant2}} \mu(\mathcal{E}(\mathcal{V}_{p^i},\mathcal{W}_{p^k})) \leqslant \frac{\mu(\mathcal{E})}{4p^{31/30}},
\end{equation}
and
\begin{equation}\label{eq:NoBadEdges3}
\mu\big(\mathcal{E}(\mathcal{V}_{p^k},\mathcal{W}\setminus\widetilde{\mathcal{W}}_{p^k})\big)
	= \sum_{\substack{j\geqslant0 \\ |j-k|\geqslant2}} \mu(\mathcal{E}(\mathcal{V}_{p^k},\mathcal{W}_{p^j})) \leqslant \frac{\mu(\mathcal{E})}{4p^{31/30}} .
\end{equation}
Hence, if we let
\[
\mathcal{E}^*=\mathcal{E}(\mathcal{V}_{p^k},\widetilde{\mathcal{W}}_{p^k})\cup \mathcal{E}(\widetilde{\mathcal{V}}_{p^k},\mathcal{W}_{p^k}) ,
\]
then \eqref{eq:NoBadEdges1}-\eqref{eq:NoBadEdges3} imply that
\[
\frac{\mu(\mathcal{E}^*)}{\mu(\mathcal{E})} \geqslant 1- \frac{1}{2p^{31/30}} - \frac{1}{2p^{3/2}} 
			\geqslant \bigg(1-\frac{1}{p^{31/30}}\bigg)^{2/3} >0 ,
\]
where we used our assumption that $p>10^{2000}$ and the inequality $(1-x)^{2/3}\leqslant 1-2x/3$ for $x\in[0,1]$ that follows from Taylor's theorem. We then consider the non-trivial GCD subgraph $G^*=(\mu,\mathcal{V},\mathcal{W},\mathcal{E}^*,\mathcal{P},f,g)$ of $G$ formed by restricting the edge set to $\mathcal{E}^*$. Note that
\eq{\label{G^*/G}
\frac{q(G^*)}{q(G)}=\Bigl(\frac{\mu(\mathcal{E}^*)}{\mu(\mathcal{E})}\Bigr)^{10} \geqslant \bigg(1-\frac{1}{p^{31/30}}\bigg)^{20/3}.
}

Now, let $(v,w)\in\mathcal{E}^*$. We have the following five possibilities: 
\begin{enumerate}
\item $v\in\mathcal{V}_{p^k}$ and $w\in\mathcal{W}_{p^k}$, in which case $p^k\|v,w$ and $p^k\|\gcd(v,w)$;
\item $v\in\mathcal{V}_{p^k}$ and $w\in\mathcal{W}_{p^{k+1}}$, in which case $p^k|v,w$ and $p^k\|\gcd(v,w)$;
\item $v\in\mathcal{V}_{p^{k+1}}$ and $w\in\mathcal{W}_{p^k}$, in which case $p^k|v,w$ and $p^k\|\gcd(v,w)$;
\item $v\in\mathcal{V}_{p^k}$ and $w\in\mathcal{W}_{p^{k-1}}$, in which case $p^k\|v$, $p^{k-1}\|w$ and $p^{k-1}\|\gcd(v,w)$;
\item $v\in\mathcal{V}_{p^{k-1}}$ and $w\in\mathcal{W}_{p^k}$, in which case $p^{k-1}\|v$, $p^k\|w$ and $p^{k-1}\|\gcd(v,w)$.
\end{enumerate}
We then set $G^+=(\mu,\mathcal{V}^+,\mathcal{W}^+,\mathcal{E}^+,\mathcal{P}\cup\{p\},f^+,g^+)$, where:
\[
\mathcal{V}^+=\mathcal{V}_{p^k}\cup\mathcal{V}_{p^{k+1}},
\quad
\mathcal{W}^+=\mathcal{W}_{p^k}\cup\mathcal{W}_{p^{k+1}},
\quad
\mathcal{E}^+=\mathcal{E}^*\cap(\mathcal{V}^+\times \mathcal{W}^+),
\]
as well as
\[
f^+\big|_\mathcal{P}=f,
\quad
f^+(p)=k,
\quad
g^+\big|_{\mathcal{P}}=g,
\quad
g^+(p)=k .
\]
By looking at possibilities (a), (b) and (c), it is easy to check that $G^+$ is a GCD subgraph of $G^*$ (and hence of $G$). Note that $\mu(\mathcal{V}^+)\geqslant \mu(\mathcal{V}_{p^k})\geqslant 1-10^{40}/p>0$. Similarly, we have $\mu(\mathcal{W}^+)>0$. Consequently, its quality satisfies the relation
\[
\frac{q(G^+)}{q(G^*)} =
	\bigg(\frac{\mu(\mathcal{E}^+)}{\mu(\mathcal{E}^*)}\bigg)^{10} 
	\bigg( \frac{\mu(\mathcal{V})}{\mu(\mathcal{V}^+)}\bigg)^{9}
	 \bigg( \frac{\mu(\mathcal{W})}{\mu(\mathcal{W}^+)}\bigg)^{9}
		\frac{1}{(1-\mathds{1}_{k\geqslant1}/p)^2(1-1/p^{31/30})^{10}} .	
\]
(This relation is valid even if $\mu(\mathcal{E}^+)=0$.) We separate two cases.

\bigskip

\noindent 
{\it Case 1:} $k=0$. 

\medskip

In this case $\mathcal{V}_{p^{k-1}}=\mathcal{W}_{p^{k-1}}=\emptyset$, so all parameters of $G^+$ are the same as those of $G^*$ except that the set of primes of $G^+$ is $\mathcal{P}\cup\{p\}$ instead of $\mathcal{P}$ and $f$,$g$ have been extended to take the value 0 at $p$. As a consequence, 
\[
\frac{q(G^+)}{q(G^*)} =
		\frac{1}{(1-1/p^{31/30})^{10}} .	
\]
In particular, by \eqref{G^*/G} we have
\[
q(G^+)=\frac{q(G^*)}{(1-1/p^{31/30})^{10}} \geqslant \frac{(1-1/p^{31/30})^{20/3}}{(1-1/p^{31/30})^{10}} q(G)\geqslant q(G)>0 .
\]
Thus the lemma follows by taking $G'=G^+$.


\bigskip

\noindent 
{\it Case 2:} $k\geqslant1$. 


\medskip

 In this case we have
\al{
\frac{q(G^+)}{q(G^*)} =
	\bigg(\frac{\mu(\mathcal{E}^+)}{\mu(\mathcal{E}^*)}\bigg)^{10} 
	\bigg( \frac{\mu(\mathcal{V})}{\mu(\mathcal{V}^+)}\bigg)^{9}
	 \bigg( \frac{\mu(\mathcal{W})}{\mu(\mathcal{W}^+)}\bigg)^{9}
		\frac{1}{(1-1/p)^2(1-1/p^{31/30})^{10}} .
\label{eq:G+}
}
We also consider the GCD subgraphs  $G_{p^k,p^{k-1}}$ and $G_{p^{k-1},p^k}$ of $G$. Notice that $\mu(\mathcal{V}_{p^k})\geqslant1-10^{40}/p>0$ for $p\geqslant 10^{2000}$. Hence, if $\mu(\mathcal{W}_{p^{k-1}})>0$, then Lemma \ref{lem:InducedGraphs} implies that
\al{
\frac{q(G_{p^k,p^{k-1}})}{q(G^*)} =
	\bigg(\frac{\mu(\mathcal{E}_{p^k,p^{k-1}})}{\mu(\mathcal{E}^*)}\bigg)^{10} 
	\bigg( \frac{\mu(\mathcal{V})}{\mu(\mathcal{V}_{p^k})}\bigg)^{9}
	 \bigg( \frac{\mu(\mathcal{W})}{\mu(\mathcal{W}_{p^{k-1}})}\bigg)^{9}
		\frac{p}{(1-1/p^{31/30})^{10}} .
\label{eq:G2}
}
Similarly, if $\mu(\mathcal{V}_{p^{k-1}})>0$, then we have 
\al{
\frac{q(G_{p^{k-1},p^k})}{q(G^*)} =
	\bigg(\frac{\mu(\mathcal{E}_{p^{k-1},p^k})}{\mu(\mathcal{E}^*)}\bigg)^{10} 
	\bigg( \frac{\mu(\mathcal{V})}{\mu(\mathcal{V}_{p^{k-1}})}\bigg)^{9}
	 \bigg( \frac{\mu(\mathcal{W})}{\mu(\mathcal{W}_{p^k})}\bigg)^{9}
		\frac{p}{(1-1/p^{31/30})^{10}} .
\label{eq:G3}
}

Since $\mu(\mathcal{V}_{p^k})\geqslant(1-10^{40}/p)\mu(\mathcal{V})$, we have that $\mu(\mathcal{V}_{p^{k-1}})\leqslant 10^{40}\mu(\mathcal{V})/p$. Similarly, we have that $\mu(\mathcal{W}_{p^{k-1}})\leqslant 10^{40}\mu(\mathcal{W})/p$. To this end, let $0\leqslant A,B\leqslant 10^{40}$ be such that
\al{
\frac{\mu(\mathcal{V}_{p^{k-1}})}{\mu(\mathcal{V})} = \frac{A}{p} 
\quad\text{and}\quad
\frac{\mu(\mathcal{W}_{p^{k-1}})}{\mu(\mathcal{W})} = \frac{B}{p}.
\label{eq:AB}
}
We note that this implies that
\[
\frac{\mu(\mathcal{V}^+)}{\mu(\mathcal{V})}\leqslant 1-\frac{A}{p}\quad\text{and}\quad\frac{\mu(\mathcal{W}^+)}{\mu(\mathcal{W})} \leqslant  1-\frac{B}{p}.
\]
We also note that $\mu(\mathcal{E}_{p^k,p^{k-1}})\leqslant \mu(\mathcal{V}_{p^k})\mu(\mathcal{W}_{p^{k-1}})\leqslant B\mu(\mathcal{V})/p$, so if $\mu(\mathcal{E}_{p^k,p^{k-1}})>0$ then $B>0$. Similarly if $\mu(\mathcal{E}_{p^{k-1},p^{k}})>0$ then $A>0$.



Combining \eqref{eq:G+} and \eqref{eq:AB} with \eqref{G^*/G}, we find
\al{
\frac{q(G^+)}{q(G)} &\geqslant
	\bigg(\frac{\mu(\mathcal{E}^+)}{\mu(\mathcal{E}^*)}\bigg)^{10} 
	\frac{1}{(1-A/p)^{9}(1-B/p)^{9}(1-1/p)^2(1-1/p^{31/30})^{10/3}} . \label{eq:ineqA}
	}
Similarly, provided $B>0$, \eqref{eq:G2}, \eqref{eq:AB} and \eqref{G^*/G} give
\al{
\frac{q(G_{p^k,p^{k-1}})}{q(G)}& \geqslant
	\bigg(\frac{\mu(\mathcal{E}_{p^k,p^{k-1}})}{\mu(\mathcal{E}^*)}\bigg)^{10} 
		\frac{p^{10}}{B^{9}(1-1/p^{31/30})^{10/3}}  \, ,\label{eq:ineqB}
		}
		and, provided $A>0$, \eqref{eq:G3}, \eqref{eq:AB} and \eqref{G^*/G} give
		\al{
\frac{q(G_{p^{k-1},p^k})}{q(G)} &\geqslant
	\bigg(\frac{\mu(\mathcal{E}_{p^{k-1},p^k})}{\mu(\mathcal{E}^*)}\bigg)^{10} 
		\frac{p^{10}}{A^{9}(1-1/p^{31/30})^{10/3}} .\label{eq:ineqC}
}
We now claim that at least one of the following inequalities holds:
\al{
\frac{\mu(\mathcal{E}^+)}{\mu(\mathcal{E}^*)}	&> 
	(1-A/p)^{9/10}(1-B/p)^{9/10}(1-1/p)^{2/10}(1-1/p^{31/30})^{1/3} \,; \label{eq:ineq1}\\
\frac{\mu(\mathcal{E}_{p^k,p^{k-1}})}{\mu(\mathcal{E}^*)}& > 
	\frac{B^{9/10}(1-1/p^{31/30})^{1/3}}{p} \,;\label{eq:ineq2}\\
\frac{\mu(\mathcal{E}_{p^{k-1},p^k})}{\mu(\mathcal{E}^*)}& > 
	\frac{A^{9/10}(1-1/p^{31/30})^{1/3}}{p} \,.\label{eq:ineq3}
}
If \eqref{eq:ineq1} holds then $q(G^+)\geqslant q(G)$ by \eqref{eq:ineqA}. If \eqref{eq:ineq2} holds, then $\mu(\mathcal{E}_{p^k,p^{k-1}})>0$, so $B>0$, and so $q(G_{p^k,p^{k-1}})\geqslant q(G)$ by \eqref{eq:ineqB} and \eqref{eq:ineq2}. Finally, if \eqref{eq:ineq3} holds, then $\mu(\mathcal{E}_{p^{k-1},p^k})>0$, so $A>0$, and so $q(G_{p^{k-1},p^k})\geqslant q(G)$ by \eqref{eq:ineqC} and \eqref{eq:ineq3}. Therefore this claim would complete the proof by choosing $G'\in\{G^+,G_{p^k,p^{k+1}},G_{p^{k+1},p^k}\}$ according to which of the inequalities \eqref{eq:ineq1}-\eqref{eq:ineq3} hold.

Since $\mu(\mathcal{E}^+)+\mu(\mathcal{E}_{p^k,p^{k-1}})+\mu(\mathcal{E}_{p^{k-1},p^k})=\mu(\mathcal{E}^*)$, at least one of \eqref{eq:ineq1}-\eqref{eq:ineq3} holds if we can prove that
\[
S:= \bigg( (1-A/p)^{\frac{9}{10}}(1-B/p)^{\frac{9}{10}}(1-1/p)^{\frac{1}{5}} 
	+ \frac{B^{\frac{9}{10}}}{p} 
	+ \frac{A^{\frac{9}{10}}}{p} \bigg) \bigg(1-\frac{1}{p^{31/30}}\bigg)^{1/3} < 1. 
\]
Using the inequality $1-x\leqslant e^{-x}$ three times, we find that
\[
S\leqslant  \bigg( \exp\Big(-\frac{9A+9B+2}{10 p} \Big) 
	+ \frac{B^{\frac{9}{10}}}{p} 
	+ \frac{A^{\frac{9}{10}}}{p} \bigg) \bigg(1-\frac{1}{p^{31/30}}\bigg)^{1/3} .	
\]
Since we also have that $e^{-x}\leqslant 1-x+x^2/2$ for $x\geqslant0$, as well as $0\leqslant A,B\leqslant 10^{40}$, we conclude that
\[
S\leqslant  \bigg( 1-\frac{9A+9B+2}{10 p}+ \frac{10^{81}}{p^2} 
	+ \frac{B^{\frac{9}{10}}}{p} 
	+ \frac{A^{\frac{9}{10}}}{p} \bigg) \bigg(1-\frac{1}{p^{31/30}}\bigg)^{1/3} .	
\]
By the arithmetic-geometric mean inequality, we have that $(9A+1)/10\geqslant A^{9/10}$ and $(9B+1)/10\geqslant B^{9/10}$, whence
\[
S\leqslant  \bigg( 1 + \frac{10^{81}}{p^2} \bigg)\bigg(1-\frac{1}{p^{31/30}}\bigg)^{1/3}.
\]
Since $(1-x)^{1/3}\leqslant 1-x/3$ for $x\in[0,1]$, we must have that $S< 1$ for $p\geqslant 10^{2000}$, thus completing the proof of the lemma.
